//! Flipper Zero RPC for Argus, the Rust port of the C++ app's device layer
//! (`plugins/flipperproto0`, `backend/flipperzero/protobufsession.*`, `backend/flipperzero/rpc/`).
//!
//! - [`proto`]: the messages, generated by prost from `proto/*.proto` (the firmware's schema).
//! - [`frame`]: the varint-length framing of the RPC stream, with hard size limits.
//! - [`session`]: the serial handshake and request/response matching.
//! - [`ops`]: read-only operations (protobuf version, device info, list, stat, storage info,
//!   MD5, file read, date/time).
//! - [`transfer`]: file trees, pulling files and folders, and the `/int` backup, with every
//!   device-supplied name checked before it touches the local disk.
//! - [`screen`]: the device's screen as a stream of frames (frames of the wrong length dropped).
//! - [`write`]: operations that change the device (write, mkdir, remove, rename, reboot,
//!   factory reset); callers ask the user first.
//! - [`restore`]: reading a backup with every entry checked, and restoring it to `/int`.
//! - [`transport`]: serial port or Unix socket. Nothing here searches for or opens a device on
//!   its own; callers name the port.

pub mod frame;
pub mod ops;
pub mod restore;
pub mod screen;
pub mod session;
pub mod transfer;
pub mod transport;
pub mod write;

pub use session::{RpcError, Session};

/// The generated message types, one module per protobuf package (`PB` is `pb`,
/// `PB_Storage` is `pb_storage`, ...).
#[allow(clippy::all, clippy::pedantic, missing_docs, rustdoc::all)]
pub mod proto {
    pub mod pb {
        include!(concat!(env!("OUT_DIR"), "/pb.rs"));
    }
    pub mod pb_storage {
        include!(concat!(env!("OUT_DIR"), "/pb_storage.rs"));
    }
    pub mod pb_system {
        include!(concat!(env!("OUT_DIR"), "/pb_system.rs"));
    }
    pub mod pb_app {
        include!(concat!(env!("OUT_DIR"), "/pb_app.rs"));
    }
    pub mod pb_gui {
        include!(concat!(env!("OUT_DIR"), "/pb_gui.rs"));
    }
    pub mod pb_gpio {
        include!(concat!(env!("OUT_DIR"), "/pb_gpio.rs"));
    }
    pub mod pb_property {
        include!(concat!(env!("OUT_DIR"), "/pb_property.rs"));
    }
    pub mod pb_desktop {
        include!(concat!(env!("OUT_DIR"), "/pb_desktop.rs"));
    }

    /// The compiled schema (a `FileDescriptorSet`), for tests that compare it with the C++
    /// app's generated nanopb code.
    pub const DESCRIPTOR_SET: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/flipper_descriptor.bin"));
}
